CREATE OR REPLACE FUNCTION public.fn_get_child_naps_by_child_and_date(p_tenant_id uuid, p_child_id uuid, p_date date)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, child_id uuid, start_time timestamp with time zone, end_time timestamp with time zone, duration_minutes integer, status character varying, outcome character varying, notes text, started_by_user_id uuid, started_by_name character varying, ended_by_user_id uuid, ended_by_name character varying, parent_visible boolean, created_at timestamp with time zone, updated_at timestamp with time zone, child_name text)  LANGUAGE sql  STABLE AS $function$     SELECT s.id, s.tenant_id, s.organization_id, s.branch_id, s.classroom_id, s.child_id,            s.start_time, s.end_time, s.duration_minutes, s.status, s.outcome, s.notes,            s.started_by_user_id, s.started_by_name, s.ended_by_user_id, s.ended_by_name,            s.parent_visible, s.created_at, s.updated_at,            CONCAT(c.first_name, ' ', c.last_name) AS child_name     FROM child_nap_sessions s     JOIN children c ON s.child_id = c.id     WHERE s.tenant_id = p_tenant_id        AND s.child_id = p_child_id       AND s.start_time::date = p_date     ORDER BY s.start_time ASC; $function$ ;
